local popen = io.popen

local function shell_output(cmd)
  local fd = popen(cmd)
  if not fd then
    return ""
  end
  local out = fd:read("*l") or ""
  fd:close()
  return out
end

local function getDumaosStatus()
  local running = tonumber(shell_output("ps w 2>/dev/null | grep procmanager | grep -v grep | wc -l"))
  if running and running > 0 then
    return "1"
  end
  return "0"
end

local function getDumaosEnabled()
  local enabled = shell_output("uci -q get dumaos.tr69.dumaos_enabled")
  if enabled == "1" then
    return "1"
  end
  return "0"
end

local function setDumaosEnabled(enabled)
  os.execute("uci -q set dumaos.tr69.dumaos_enabled=" .. (enabled and "1" or "0"))
  os.execute("uci -q commit dumaos")
  local action = enabled and "start" or "stop"
  -- Do not stop DumaOS from inside Transformer's request handler: DumaOS
  -- cleanup can wait on ubus and would deadlock the setter. The helper runs
  -- after the RPC response has been returned.
  os.execute("(sleep 1; /usr/lib/dumaos/platform/control.sh " .. action .. ") >/dev/null 2>&1 &")
end

local dumaos_ = {
    objectType = {
        name = 'rpc.dumaos.',
        access = 'readOnly',
        minEntries = 1,
        maxEntries = 1,
        parameters = {
            status = {
                access = "readOnly",
                type = "unsignedInt",
            },
            enabled = {
                access = "readWrite",
                type = "boolean",
            }
        }
    },
    get = {
        status = getDumaosStatus,
        enabled = getDumaosEnabled,
    },
    set = {
        enabled = function(mapping, paramname, paramvalue)
            setDumaosEnabled(paramvalue == "1")
        end,
    }
}

register(dumaos_)
